            g=c.Graph.__new__(c.Graph);g.g=result;g.count=len(result.nodes);g.frame=None
            inp,=[node for node in result.nodes if node.type=='GROUP_INPUT']
            metric,=[node for node in result.nodes if node.label=='Corner-pattern shape admission']
