            g.bind(source,repair.inputs['Geometry']);g.bind(inp.outputs['Mouths'],repair.inputs['Mouths'])
            g.bind(c._read(g,inp.outputs['Plan'],'st_cq_count',0,'INT'),repair.inputs['Rows'])
            g.bind(inp.outputs['Input Valid'],repair.inputs['Input Valid'])
